var i=`0296-turli-tava`;var n=`world-0296`;var a=`MK`;var o=`southern-europe`;var r=4;var s=63;var l={en:`Turli Tava`,ua:`Турлі тава`};var g={en:`A traditional North Macedonia dish made with chicken thigh, eggplant, yellow onion, carrot. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Північна Македонія. Основні інгредієнти: куряче стегно, баклажан, жовта цибуля, морква. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`chicken-thigh`,450,`g`],[`eggplant`,340,`g`],[`extra-virgin-olive-oil`,50,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,170,`g`],[`carrot`,150,`g`],[`green-bell-pepper`,170,`g`],[`tomato`,230,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 43 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 43 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:43,i:[[`potato`,350,`g`],[`water`,400,`ml`],[`sweet-paprika`,5,`g`],[`table-salt`,null,`to_taste`]]}];var h={slug:i,id:n,country:`MK`,region:o,servings:4,minutes:63,title:l,text:g,steps:u};export{a as country,h as default,n as id,s as minutes,o as region,r as servings,i as slug,u as steps,g as text,l as title};